package config

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
)

type Identity struct {
	Lead   IdentityRole `toml:"lead" json:"lead"`
	Worker WorkerRole   `toml:"worker" json:"worker"`
}

type IdentityRole struct {
	Name        string `toml:"name" json:"name"`
	Persona     string `toml:"persona" json:"persona"`
	Language    string `toml:"language" json:"language"`
	AddressUser string `toml:"address_user" json:"address_user"`
}

type WorkerRole struct {
	DisplayPrefix string `toml:"display_prefix" json:"display_prefix"`
}

type Lead struct {
	Kind     string            `toml:"kind" json:"kind"`
	Profiles map[string]string `toml:"profiles" json:"profiles"`
}

type Defaults struct {
	MaxWorkers          int    `toml:"max_workers" json:"max_workers"`
	DispatchInheritance string `toml:"dispatch_inheritance" json:"dispatch_inheritance"`
	StallAfter          string `toml:"stall_after" json:"stall_after"`
	IdleAfter           string `toml:"idle_after" json:"idle_after"`
	AutoTeardown        string `toml:"auto_teardown" json:"auto_teardown"`
	RecoveryAttempts    int    `toml:"recovery_attempts" json:"recovery_attempts"`
	RecoveryBackoff     string `toml:"recovery_backoff" json:"recovery_backoff"`
	MergeMode           string `toml:"merge_mode" json:"merge_mode"`
	TargetBranch        string `toml:"target_branch" json:"target_branch"`
	MergeMethod         string `toml:"merge_method" json:"merge_method"`
	// RequireCurrentTarget enables ADR 0019's current-target rule and the
	// ADR 0031 merge queue; off by default.
	RequireCurrentTarget bool   `toml:"require_current_target" json:"require_current_target"`
	Forge                string `toml:"forge" json:"forge"`
	PRPoll               string `toml:"pr_poll" json:"pr_poll"`
	Review               string `toml:"review" json:"review"`
	DeleteBranchOnMerge  bool   `toml:"delete_branch_on_merge" json:"delete_branch_on_merge"`
}

type ReviewLoop struct {
	Enabled           bool     `toml:"enabled" json:"enabled"`
	GreenhouseTimeout string   `toml:"greenhouse_timeout" json:"greenhouse_timeout"`
	MaxRounds         int      `toml:"max_rounds" json:"max_rounds"`
	BlockAt           string   `toml:"block_at" json:"block_at"`
	AutoStart         bool     `toml:"auto_start" json:"auto_start"`
	Docs              bool     `toml:"docs" json:"docs"`
	Guidance          []string `toml:"guidance" json:"guidance"`
	Profile           string   `toml:"profile" json:"profile"`
}

type CILoop struct {
	MaxFixRounds   int    `toml:"max_fix_rounds" json:"max_fix_rounds"`
	RerunCancelled int    `toml:"rerun_cancelled" json:"rerun_cancelled"`
	FlakeWindow    string `toml:"flake_window" json:"flake_window,omitempty"`
}

// FlakeWindowDuration is how far back a failure on another branch makes a
// failing test a known flake. Zero, including a plan frozen before the
// setting existed, disables flake reruns.
func (c CILoop) FlakeWindowDuration() time.Duration {
	window, err := time.ParseDuration(c.FlakeWindow)
	if err != nil {
		return 0
	}
	return window
}

type FullPipeline struct {
	RunWorkflows bool `toml:"run_workflows" json:"run_workflows"`
}

type Pipeline struct {
	CandidateFiles []string `toml:"candidate_files" json:"candidate_files"`
}

type Pool struct {
	Clean    string   `toml:"clean" json:"clean"`
	Setup    []string `toml:"setup" json:"setup"`
	KeepIdle int      `toml:"keep_idle" json:"keep_idle"`
}

// Research bounds tracked native research children (ADR 0029).
type Research struct {
	Native         string `toml:"native" json:"native"`
	MaxActive      int    `toml:"max_active" json:"max_active"`
	MaxResultBytes int    `toml:"max_result_bytes" json:"max_result_bytes"`
	MaxOutputBytes int    `toml:"max_output_bytes" json:"max_output_bytes"`
	Timeout        string `toml:"timeout" json:"timeout"`
}

// Research modes: tracked admits read-only children through Posse; off leaves
// harness children unmanaged and refuses `posse research start`.
const (
	ResearchTracked = "tracked"
	ResearchOff     = "off"
)

var DefaultResearch = Research{Native: ResearchTracked, MaxActive: 2, MaxResultBytes: 256 << 10, MaxOutputBytes: 8 << 20, Timeout: "30m"}

type Retention struct {
	TaskArtifacts string `toml:"task_artifacts" json:"task_artifacts"`
}

// Up selects the Projects `posse up --all` restores; nil Projects restores
// every Project that is not down.
type Up struct {
	Projects []string `toml:"projects" json:"projects"`
}

// WorkerGoCache bounds the Posse-owned Go build cache shared by every Worker.
// It is valid only in the User config because the cache spans Projects.
type WorkerGoCache struct {
	MaxSize  string `toml:"max_size" json:"max_size"`
	MinAge   string `toml:"min_age" json:"min_age"`
	Interval string `toml:"interval" json:"interval"`
}

// MinWorkerGoCacheAge is the shortest allowed worker_go_cache.min_age. Go
// refreshes a cache entry's mtime only when it is over an hour old, so a
// longer floor keeps every entry used within the last hour.
const MinWorkerGoCacheAge = 2 * time.Hour

var DefaultWorkerGoCache = WorkerGoCache{MaxSize: "8GiB", MinAge: "6h", Interval: "1h"}

type Kind struct {
	Disabled           bool     `toml:"disabled" json:"disabled"`
	AutoApproveArgs    []string `toml:"auto_approve_args" json:"auto_approve_args"`
