func removeFixtureTaskPane(fixture *prMergeFixture) {
	remove := func(snapshot herdr.Snapshot) herdr.Snapshot {
		panes := snapshot.Panes[:0]
		for _, pane := range snapshot.Panes {
			if pane.PaneID != fixture.task.PaneID && pane.Label != fixture.task.PaneLabel {
				panes = append(panes, pane)
			}
		}
		snapshot.Panes = panes
		agents := snapshot.Agents[:0]
		for _, agent := range snapshot.Agents {
			if agent.PaneID != fixture.task.PaneID {
				agents = append(agents, agent)
			}
		}
		snapshot.Agents = agents
		return snapshot
	}
	switch adapter := fixture.service.Herdr.(type) {
	case *herdr.Fake:
		adapter.SnapshotValue = remove(adapter.SnapshotValue)
	case *changingSnapshotAdapter:
		adapter.mu.Lock()
		adapter.snapshot = remove(adapter.snapshot)
		adapter.mu.Unlock()
	}
}

// requireCurrentTarget enables ADR 0019's current-target rule, which is off
// by default, in the fixture's User config.
func (fixture *prMergeFixture) requireCurrentTarget(t *testing.T) {
	t.Helper()
	path := filepath.Join(fixture.home, "config.toml")
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	updated := strings.Replace(string(content), "[defaults]\n", "[defaults]\nrequire_current_target = true\n", 1)
	if updated == string(content) {
		t.Fatalf("fixture config has no [defaults] table: %s", content)
	}
	if err := os.WriteFile(path, []byte(updated), 0o600); err != nil {
		t.Fatal(err)
	}
}

