func (db *DB) GreenhouseGatePass(ctx context.Context, taskID int64, repository, head string) (bool, error) {
	rows, err := db.QueryContext(ctx, `SELECT verdict,blocking,head_sha,mode FROM verdicts WHERE task_id=? AND repo=? AND provider=? ORDER BY recorded_at DESC,id DESC`, taskID, repository, GreenhouseReviewProvider)
	if err != nil {
		return false, err
	}
	defer rows.Close()
	if !rows.Next() {
		return false, rows.Err()
	}
	var verdict Verdict
	if err := rows.Scan(&verdict.Outcome, &verdict.Blocking, &verdict.Head, &verdict.Mode); err != nil {
		return false, err
	}
	return verdict.Qualifies(head), rows.Err()
}

func countBlockingReviewFindingsTx(ctx context.Context, tx *writeTx, taskID int64, repository, blockAt string) (int, error) {
	threshold := map[string]int{"P0": 0, "P1": 1, "P2": 2}[blockAt]
	rows, err := tx.QueryContext(ctx, `SELECT severity FROM review_findings WHERE ship_task_id=? AND repository=? AND origin='introduced' AND in_scope=1 AND state IN ('open','fix_claimed','unverified','disputed','regressed')`, taskID, repository)
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	blocking := 0
	for rows.Next() {
		var severity string
		if err := rows.Scan(&severity); err != nil {
			return 0, err
		}
		rank, known := map[string]int{"P0": 0, "P1": 1, "P2": 2, "P3": 3}[severity]
		if !known || rank <= threshold {
			blocking++
		}
	}
	return blocking, rows.Err()
}

