182: // markdown renders the block that lives inside a tokenized PR body span.
183: func (summary validationSummary) markdown() string {
184: 	head := "unknown"
185: 	if summary.Head != "" {
186: 		head = "`" + shortSHA(summary.Head) + "`"
187: 	}
188: 	rounds := fmt.Sprintf("%d used, %d remaining of %d", summary.RoundsUsed, summary.Remaining, summary.MaxRounds)
189: 	if summary.MaxRounds == 0 {
190: 		rounds = "review loop off"
191: 	}
192: 	verdict := defaultValue(summary.LatestVerdict, "none yet")
193: 	findings := "none"
194: 	if states := summary.findingStates(); len(states) > 0 {
195: 		parts := make([]string, 0, len(states))
196: 		for _, state := range states {
197: 			parts = append(parts, fmt.Sprintf("%s %d", state, summary.Findings[state]))
198: 		}
199: 		findings = strings.Join(parts, ", ")
200: 	}
201: 	accepted := "none"
202: 	if len(summary.Accepted) > 0 {
203: 		accepted = strings.Join(summary.Accepted, "; ")
204: 	}
205: 	return strings.Join([]string{
206: 		validationBlockStart,
207: 		"## Validation",
208: 		"",
209: 		"- Head: " + head,
210: 		"- Review: " + summary.Review + " (" + rounds + "; latest verdict: " + verdict + ")",
211: 		"- Findings: " + findings,
212: 		fmt.Sprintf("- Carries: %d, dispositions: %d", summary.Carries, summary.Dispositions),
213: 		"- Accepted at review cap: " + accepted,
214: 		"- CI: " + summary.CI,
215: 		validationBlockEnd,
216: 	}, "\n")
217: }
